```python
import sys

def main():
    s = sys.stdin.readline().strip()
    N = len(s)
    solve = []
    i = 0
    while i < N:
        if i + 3 <= N and s[i:i+3] == "dot":
            solve.append('.')
            i += 3
        elif i + 2 <= N and s[i:i+2] == "at":
            solve.append('@')
            i += 2
        else:
            solve.append(s[i])
            i += 1
    solve = ''.join(solve)

    # Check function
    if solve.startswith('.'):
        solve = "dot" + solve[1:]
    elif solve.startswith('@'):
        solve = "at" + solve[1:]
    if solve.endswith('.'):
        solve = solve[:-1] + "dot"
    elif solve.endswith('@'):
        solve = solve[:-1] + "at"

    cont = solve.count('@')
    if cont == 1:
        print(solve)
    else:
        ok = True
        res = []
        for ch in solve:
            if ch == '@':
                if ok:
                    res.append('@')
                    ok = False
                else:
                    res.append('at')
            else:
                res.append(ch)
        print(''.join(res))

if __name__ == "__main__":
    main()
```

